// Generated by the Salvo compiler: the actor scheduler — asynchronous
// effect handlers' runtime. The Kotlin mirror of the Rust backend's
// scheduler module; the semantics are LANGUAGE_SPEC.md's [actor-kind] …
// [actor-watch] and must stay identical on both
// backends: run-to-completion activations on pool threads, per-actor
// bounded queues (bound explicit at spawn; a full queue blocks the
// sender), reply tokens with reserved capacity (a reply never blocks and
// never counts against the bound), the gate (at most one outstanding per
// actor; while gated only the awaited reply is delivered), death = a
// faulted activation caught at the dispatch boundary (sends and replies
// to the dead are silent no-ops; watchers are notified with the reason),
// and the idle-with-parked-gates report. Pool threads are daemon threads:
// the program ends when main returns.
//
// [main-pool] [waitfor-pump] `main` is the **single worker of its own pool**
// (pool 0), which is given no thread of its own: main's thread is the
// worker, and it works while it waits. A wait therefore *serves* its pool
// rather than merely blocking on it — the uniform rule is that a `waitfor`
// serves its own pool's work except activations of the actor doing the
// waiting, so a waiting actor's mailbox stays stalled (serialization is
// preserved) while main, which has no mailbox, serves everything placed on
// its pool. Blocking is the degenerate case of an empty queue.
package salvo

import kotlin.concurrent.withLock

/** An actor body: state plus one entry point per kind of delivery. */
interface SalvoActor {
    /** A user message (a `send fn` invocation). */
    fun handle(ctx: SalvoCtx, msg: Any?)

    /** A reply delivery: the slot names the parked continuation. */
    fun resume(ctx: SalvoCtx, slot: Long, value: Any?)
}

/** Passed to every activation: the actor's own identity. */
class SalvoCtx(val addr: Int)

private sealed class SalvoEntry {
    class User(val msg: Any?) : SalvoEntry()

    class Reply(val slot: Long, val value: Any?) : SalvoEntry()
}

private class SalvoActorState(val bound: Int, val pool: Int, var body: SalvoActor?) {
    val queue = ArrayDeque<SalvoEntry>()
    var userLen = 0
    var gate: Long? = null
    var running = false
    var dead = false

    /**
     * The host's account of the fault that killed it, kept so a watch
     * registered *after* the death answers what the earlier watchers got.
     */
    var exitReason: String? = null

    /**
     * [actor-watch] Registered death watches: the token to fulfil and the
     * **builder** generated code handed over with it, which turns the reason
     * into the language's `Exit` value. The runtime cannot construct a Salvo
     * class, so the watch site supplies the constructor.
     */
    val watchers = mutableListOf<Pair<SalvoReply, (String) -> Any?>>()
}

private class SalvoWaiterState {
    var value: Any? = null
    var filled = false
}

/**
 * [main-pool] [waitfor-pump] Where a thread is: the pool it works for, and
 * the actor whose activation it is currently inside (`null` on main and
 * between activations). The pool is what an `on`-less spawn or mint
 * inherits; the actor is the one thing a wait must not serve.
 */
private class SalvoHere(val pool: Int, val actor: Int?)

/**
 * [task-mint] What a pool owns besides its worker threads: a queue of
 * detached tasks, and the sink an uncaught fault on it is reported to
 * [pool-fault-sink] (`null` is the named runtime report).
 */
private class SalvoPoolState {
    /** Tasks whose answer has arrived, in the order it arrived. */
    val tasks = ArrayDeque<Pair<(Any?) -> Unit, Any?>>()
    var sinkAddr: Int? = null
    var sinkBuild: ((String) -> Any?)? = null
}

/**
 * The scheduler: one shared lock (its own monitor) over all state, pool
 * worker threads, and the waiter bridge for `main`.
 */
object SalvoSched {
    /**
     * [main-pool] The pool main is the single worker of. It never gets a
     * worker thread: main's own thread runs its work, while it waits.
     */
    const val MAIN_POOL = 0

    private val lock = java.util.concurrent.locks.ReentrantLock()
    private val cv = lock.newCondition()
    private val actors = mutableListOf<SalvoActorState>()
    private val waiters = mutableListOf<SalvoWaiterState>()
    // [main-pool] Pool 0 exists from the start and belongs to main.
    private val pools = mutableListOf(SalvoPoolState())
    private var nextSlot = 0L
    private var active = 0
    private val here = ThreadLocal.withInitial { SalvoHere(MAIN_POOL, null) }

    /** Creates a pool of [n] daemon worker threads and answers its id. */
    fun pool(n: Int): Int = poolWithSink(n, null, null)

    /**
     * [pool-fault-sink] The same, with an actor to report uncaught faults to:
     * the addr and the builder that turns the host's reason into the
     * language's `Fault` value (the runtime cannot construct one, exactly as
     * with `Exit` [actor-watch]).
     */
    fun poolWithSink(
        n: Int,
        sinkAddr: Int?,
        sinkBuild: ((String) -> Any?)?,
    ): Int {
        val id =
            lock.withLock {
                val state = SalvoPoolState()
                state.sinkAddr = sinkAddr
                state.sinkBuild = sinkBuild
                pools.add(state)
                pools.size - 1
            }
        repeat(n) {
            Thread { worker(id) }.apply {
                isDaemon = true
                start()
            }
        }
        return id
    }

    /**
     * [task-mint] Mints a token whose fulfilment **schedules** [body] on
     * [pool]. No capacity is reserved and no queue can be full: a task has no
     * mailbox, which is why a task mint contributes no deadlock edge.
     */
    fun mintTask(
        pool: Int,
        body: (Any?) -> Unit,
    ): SalvoReply =
        lock.withLock {
            nextSlot += 1
            SalvoReply(SalvoTargetTask(pool, body), nextSlot)
        }

    /**
     * [main-pool] The pool the calling thread works for — what a spawn or a
     * mint with no `on` clause inherits. Main's thread answers [MAIN_POOL].
     */
    fun currentPool(): Int = here.get().pool

    /**
     * [waitfor-dedicated] A pool of exactly one thread, for work that may
     * occupy its thread until an answer arrives. Identical to `pool(1)` at
     * run time — what makes it different is static: the language types it as
     * a `Dedicated Pool` and the `on` clause consumes it, so a dedicated
     * thread has exactly one occupant.
     */
    fun thread(): Int = pool(1)

    /** Spawns an actor on a pool. The queue bound is explicit and required. */
    fun spawn(pool: Int, bound: Int, body: SalvoActor): Int =
        lock.withLock {
            actors.add(SalvoActorState(bound, pool, body))
            actors.size - 1
        }

    /**
     * Sends a user message. Blocks while the target's queue is full; a
     * send to a dead actor is a silent no-op.
     *
     * [main-pool] One block is a *guaranteed* wedge rather than
     * back-pressure: the main pool has exactly one worker — main's own
     * thread, which serves work only inside a `waitfor` — so a full
     * main-pool mailbox blocked on from that same thread can never drain.
     * Reported by name instead of hung.
     */
    fun send(addr: Int, msg: Any?) {
        lock.withLock {
            while (!actors[addr].dead && actors[addr].userLen >= actors[addr].bound) {
                if (currentPool() == MAIN_POOL && actors[addr].pool == MAIN_POOL) {
                    reportMainPoolWedge(addr)
                }
                cv.await()
            }
            if (actors[addr].dead) {
                return
            }
            actors[addr].queue.addLast(SalvoEntry.User(msg))
            actors[addr].userLen += 1
            cv.signalAll()
        }
    }

    /**
     * [main-pool] The full-main-pool-mailbox report: a named error, since
     * the only thread that could drain the queue is the one blocked on it.
     */
    private fun reportMainPoolWedge(addr: Int): Nothing {
        System.err.println(
            "salvo: deadlock: the main pool's actor $addr has a full mailbox and the " +
                "only thread that could drain it is the one sending: the main pool has one " +
                "worker, `main` itself, and it serves work only inside a `waitfor` — send " +
                "fewer messages before waiting, raise the handler's `mailbox` capacity, or " +
                "place the actor on a pool of its own",
        )
        kotlin.system.exitProcess(1)
    }

    /**
     * Mints a reply token targeting a actor's parked continuation, and
     * answers the slot beside it: the slot is what generated code keys its
     * parked-continuation table by. A `Pair`, like [waiter], and the mirror
     * of the Rust runtime's `salvo_mint`.
     */
    fun mint(addr: Int): Pair<SalvoReply, Long> =
        lock.withLock {
            nextSlot += 1
            Pair(SalvoReply(SalvoTargetProc(addr), nextSlot), nextSlot)
        }

    /**
     * Mints a *gated* reply token: until it is delivered, the actor
     * serves nothing else. At most one gate may be outstanding — a second
     * is a fault in the calling activation.
     */
    fun mintGated(addr: Int): Pair<SalvoReply, Long> =
        lock.withLock {
            check(actors[addr].gate == null) { "a gated continuation is already outstanding" }
            nextSlot += 1
            actors[addr].gate = nextSlot
            Pair(SalvoReply(SalvoTargetProc(addr), nextSlot), nextSlot)
        }

    /**
     * [actor-watch] Registers a death watch: [onExit] is sent the `Exit`
     * [exit] builds when the actor dies. Watching an already-dead actor
     * answers immediately, with the reason its death recorded — so a watch
     * that loses the race to a fast fault is not a watch that never answers.
     */
    fun watch(
        addr: Int,
        onExit: SalvoReply,
        exit: (String) -> Any?,
    ) {
        lock.withLock {
            if (actors[addr].dead) {
                deliverReply(onExit, exit(actors[addr].exitReason ?: "fault"))
                cv.signalAll()
            } else {
                actors[addr].watchers.add(Pair(onExit, exit))
            }
        }
    }

    /** A waiter: the `waitfor` bridge. Answers (token, waiter id). */
    fun waiter(): Pair<SalvoReply, Int> =
        lock.withLock {
            waiters.add(SalvoWaiterState())
            nextSlot += 1
            Pair(SalvoReply(SalvoTargetWaiter(waiters.size - 1), nextSlot), waiters.size - 1)
        }

    /**
     * [waitfor-pump] Blocks the calling thread until the waiter's token is
     * sent, and answers the value — *serving this thread's pool while it
     * waits* (everything on it except the waiting actor's own activations,
     * which stay stalled). For main, whose pool has no other worker, that is
     * what runs main-pool work at all; where the queue is empty the wait is a
     * plain block. If the scheduler is idle and can never fulfil the token,
     * reports the deadlock instead of hanging.
     */
    fun awaitReply(wid: Int): Any? {
        val spot = here.get()
        lock.lock()
        try {
            while (true) {
                if (waiters[wid].filled) {
                    waiters[wid].filled = false
                    return waiters[wid].value
                }
                // [waitfor-pump] Detached tasks are what the rule names
                // first, and they are served whoever is waiting; activations
                // are served except the waiter's own.
                if (pools[spot.pool].tasks.isNotEmpty()) {
                    runTask(spot.pool)
                    continue
                }
                val job = pick(spot.pool, spot.actor)
                if (job != null) {
                    runJob(job.first, job.second)
                    continue
                }
                if (idle()) {
                    reportDeadlock(spot.actor)
                }
                cv.await()
            }
        } finally {
            lock.unlock()
        }
    }

    internal fun sendReply(reply: SalvoReply, value: Any?) {
        lock.withLock {
            deliverReply(reply, value)
            cv.signalAll()
        }
    }

    /** Delivery under the lock: reserved capacity, no-op to the dead. */
    private fun deliverReply(reply: SalvoReply, value: Any?) {
        when (val target = reply.target) {
            is SalvoTargetWaiter -> {
                waiters[target.wid].value = value
                waiters[target.wid].filled = true
            }
            is SalvoTargetProc -> {
                if (actors[target.addr].dead) {
                    return
                }
                actors[target.addr].queue.addLast(SalvoEntry.Reply(reply.slot, value))
            }
            // [task-mint] The answer schedules the task. Nothing to check: a
            // task has no mailbox to fill and no death to be a no-op for.
            is SalvoTargetTask -> {
                pools[target.pool].tasks.addLast(Pair(target.body, value))
            }
        }
    }

    /** The first deliverable entry for an actor, honouring the gate. */
    private fun deliverable(p: SalvoActorState): Int? {
        if (p.running || p.dead) {
            return null
        }
        val gate = p.gate ?: return if (p.queue.isEmpty()) null else 0
        val at = p.queue.indexOfFirst { it is SalvoEntry.Reply && it.slot == gate }
        return if (at < 0) null else at
    }

    /** True when nothing can ever run again without outside input. */
    private fun idle(): Boolean =
        active == 0 && actors.all { deliverable(it) == null } && pools.all { it.tasks.isEmpty() }

    /**
     * [waitfor-pump] The next job a thread working for [pool] may run:
     * [exclude] is the actor whose own activation is waiting, which a wait
     * must never serve — re-entering an actor mid-activation is precisely
     * what serialization exists to prevent. A pool worker excludes nothing.
     */
    private fun pick(
        pool: Int,
        exclude: Int?,
    ): Pair<Int, Int>? =
        actors.withIndex().firstNotNullOfOrNull { (i, p) ->
            if (p.pool != pool || i == exclude) null else deliverable(p)?.let { Pair(i, it) }
        }

    /**
     * The idle-with-parked-gates report [actor-watch]. [waiter] names the
     * frame that is waiting, which since [waitfor-effect] need not be main.
     */
    private fun reportDeadlock(waiter: Int?): Nothing {
        val parked =
            actors.withIndex().filter { it.value.gate != null && !it.value.dead }.map { "actor ${it.index}" }
        val who = if (waiter == null) "main" else "actor $waiter"
        System.err.println(
            "salvo: deadlock: all actors idle while $who waits" +
                if (parked.isEmpty()) "" else " (parked gates: ${parked.joinToString(", ")})",
        )
        kotlin.system.exitProcess(1)
    }

    /**
     * Runs one activation to completion. Called with the lock held and
     * answers with it held, releasing it for the body itself: a fault is
     * caught at this boundary and becomes the actor's death. Both callers —
     * a pool worker and a `waitfor` pumping its own pool [waitfor-pump] — go
     * through here, so an activation means the same thing whichever thread
     * runs it.
     */
    private fun runJob(
        addr: Int,
        at: Int,
    ) {
        val p = actors[addr]
        val entry = p.queue.removeAt(at)
        if (entry is SalvoEntry.User) {
            p.userLen -= 1
        }
        if (entry is SalvoEntry.Reply && p.gate == entry.slot) {
            p.gate = null
        }
        val body = p.body
        p.body = null
        p.running = true
        active += 1
        cv.signalAll() // a user entry left the queue
        lock.unlock()

        // The activation runs *here*: an ambient mint inside it inherits this
        // pool, and a nested wait must not serve this actor [waitfor-pump].
        val spot = here.get()
        here.set(SalvoHere(p.pool, addr))
        val ctx = SalvoCtx(addr)
        var fault: String? = null
        try {
            when (entry) {
                is SalvoEntry.User -> body!!.handle(ctx, entry.msg)
                is SalvoEntry.Reply -> body!!.resume(ctx, entry.slot, entry.value)
            }
        } catch (t: Throwable) {
            fault = t.message ?: t.javaClass.simpleName
        } finally {
            here.set(spot)
            lock.lock()
        }
        p.running = false
        active -= 1
        // A local `val`, because a captured `var` does not smart-cast
        // inside a lambda and the `Exit` builder wants a `String`.
        val reason = fault
        if (reason == null) {
            p.body = body
        } else {
            p.dead = true
            p.exitReason = reason
            p.queue.clear()
            p.userLen = 0
            p.gate = null
            val watchers = p.watchers.toList()
            p.watchers.clear()
            for ((w, exit) in watchers) {
                deliverReply(w, exit(reason))
            }
            // [pool-fault-sink] The net under supervision: a death nobody was
            // watching still reaches the pool's sink, or the named report.
            if (watchers.isEmpty()) {
                reportFault(p.pool, reason)
            }
        }
        cv.signalAll()
    }

    /**
     * [task-mint] Runs one detached task to completion, with the same lock
     * discipline and fault boundary as an activation: the lock is released for
     * the body, and a fault is caught here. A task has no identity, so there
     * is nothing to mark dead and nobody to notify — the fault goes to the
     * pool's sink [pool-fault-sink], or to the named report when it has none.
     */
    private fun runTask(pool: Int) {
        val job = pools[pool].tasks.removeFirstOrNull() ?: return
        active += 1
        lock.unlock()

        // A task belongs to no actor, so a nested wait inside it may serve
        // every activation on the pool [waitfor-pump].
        val spot = here.get()
        here.set(SalvoHere(pool, null))
        var fault: String? = null
        try {
            job.first(job.second)
        } catch (t: Throwable) {
            fault = t.message ?: t.javaClass.simpleName
        } finally {
            here.set(spot)
            lock.lock()
        }
        active -= 1
        val reason = fault
        if (reason != null) {
            reportFault(pool, reason)
        }
        cv.signalAll()
    }

    /**
     * [pool-fault-sink] Where an uncaught fault on a pool goes: a message to
     * the pool's sink actor if it has one, else a named report on stderr. A
     * fault that cannot be delivered (a dead sink) falls back to the report,
     * since the alternative is losing it silently.
     */
    private fun reportFault(
        pool: Int,
        reason: String,
    ) {
        val addr = pools[pool].sinkAddr
        val build = pools[pool].sinkBuild
        if (addr != null && build != null && !actors[addr].dead) {
            // Enqueued past the bound deliberately: a fault report must not
            // block the faulting thread, and dropping it would lose the one
            // thing the sink exists for.
            actors[addr].queue.addLast(SalvoEntry.User(build(reason)))
            actors[addr].userLen += 1
            return
        }
        System.err.println("salvo: an uncaught fault on pool $pool: $reason")
    }

    private fun worker(pool: Int) {
        here.set(SalvoHere(pool, null))
        lock.lock()
        try {
            while (true) {
                // [task-mint] A queued task before an activation: one rule,
                // the same on both backends, so a program's interleaving does
                // not depend on its target. Each queue is served in arrival
                // order.
                if (pools[pool].tasks.isNotEmpty()) {
                    runTask(pool)
                    continue
                }
                val job = pick(pool, null)
                if (job == null) {
                    cv.await()
                } else {
                    runJob(job.first, job.second)
                }
            }
        } finally {
            lock.unlock()
        }
    }
}

internal sealed class SalvoTarget

internal class SalvoTargetProc(val addr: Int) : SalvoTarget()

internal class SalvoTargetWaiter(val wid: Int) : SalvoTarget()

/** [task-mint] A detached one-shot: the pool it runs on, and the closure. */
internal class SalvoTargetTask(val pool: Int, val body: (Any?) -> Unit) : SalvoTarget()

/**
 * A one-shot reply capability. `send` delivers exactly once — the
 * guarantee is the checker's; the runtime only enqueues.
 */
class SalvoReply internal constructor(internal val target: SalvoTarget, internal val slot: Long) {
    fun send(value: Any?) = SalvoSched.sendReply(this, value)
}
